window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5f65348b962f04bc"]={"versions": [{"id": "FIG-5f65348b962f04bc", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Metamodell- und Prozessdiagramm der AUTOSAR-Methodik (Work Product Definition). Das Diagramm spezifiziert die Spezialisierungshierarchie von Artefakt-Bündeln (Work Product Kinds) für die Basissoftware-Integration sowie deren Aggregation von Teil-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Paket-Artefakte (Work Product Definitions bzw. Packages) in einer Spezialisierungskette:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Bundle</code>: Basis-Artefaktpaket.\n</li><li><code>BSW Module Delivered Bundle</code>: Spezialisiert <code>BSW Module Bundle</code> über eine Generalisierungsbeziehung (<code>«extends»</code>).\n</li><li><code>BSW Module Integration Bundle</code>: Spezialisiert <code>BSW Module Delivered Bundle</code> über eine Generalisierungsbeziehung (<code>«extends»</code>).\n</li></ul>\n<p class=\"fig-p\">Vom <code>BSW Module Integration Bundle</code> gehen vier Aggregationsbeziehungen (<code>«SPEM_Aggregation»</code>) mit Kardinalität <code>0..*</code> zu einzelnen Arbeitsergebnissen/Dokumenten (Work Products) aus:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Interface Extension</code>: Zusätzliche Schnittstellendefinitionen für das BSW-Modul (Kardinalität <code>0..*</code>).\n</li><li>Drei weitere untergeordnete BSW-Artefakte am unteren Rand (BSW-Modulbeschreibungen, Verhaltensbeschreibungen und lokale Konfigurations-/Messgrößendefinitionen wie <code>BSW Module Behavior</code>, <code>BSW Module ...</code>, <code>Local Measurement...</code>), jeweils aggregiert mit Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Definitionsdiagramm ohne Laufzeit- oder Sequenzcharakter. Im methodischen Ablauf beschreibt es die Bereitstellung und Anreicherung von BSW-Lieferbündeln im Rahmen der Integrationsphase: Das generische Lieferbündel (<code>BSW Module Delivered Bundle</code>) wird für die konkrete ECU- und Systemintegration zum <code>BSW Module Integration Bundle</code> erweitert, indem modulspezifische Schnittstellenerweiterungen, Verhaltensmodelle und lokale Integrationsparameter gebündelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Work-Product-Struktur für AUTOSAR BSW-Lieferungen und -Integration. Entwickler und Tool-Hersteller von AUTOSAR-Authoring- und Integrationswerkzeugen müssen sicherstellen, dass Integrationsbündel alle spezialisierten Artefakte des gelieferten Bündels erben und zusätzliche integrationsspezifische Deskriptoren (0 bis n Ausprägungen pro aggregiertem Work Product) konsistent kapseln.</p>"}, {"id": "FIG-50f5393d10d0966d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Metamodell- und Prozessdiagramm der AUTOSAR-Methodik (Work Product Definition). Das Diagramm spezifiziert die Spezialisierungshierarchie von Artefakt-Bündeln (Work Product Kinds) für die Basissoftware-Integration sowie deren Aggregation von Teil-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Paket-Artefakte (Work Product Definitions bzw. Packages) in einer Spezialisierungskette:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Bundle</code>: Basis-Artefaktpaket.\n</li><li><code>BSW Module Delivered Bundle</code>: Spezialisiert <code>BSW Module Bundle</code> über eine Generalisierungsbeziehung (<code>«extends»</code>).\n</li><li><code>BSW Module Integration Bundle</code>: Spezialisiert <code>BSW Module Delivered Bundle</code> über eine Generalisierungsbeziehung (<code>«extends»</code>).\n</li></ul>\n<p class=\"fig-p\">Vom <code>BSW Module Integration Bundle</code> gehen vier Aggregationsbeziehungen (<code>«SPEM_Aggregation»</code>) mit Kardinalität <code>0..*</code> zu einzelnen Arbeitsergebnissen/Dokumenten (Work Products) aus:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Interface Extension</code>: Zusätzliche Schnittstellendefinitionen für das BSW-Modul (Kardinalität <code>0..*</code>).\n</li><li>Drei weitere untergeordnete BSW-Artefakte am unteren Rand (BSW-Modulbeschreibungen, Verhaltensbeschreibungen und lokale Konfigurations-/Messgrößendefinitionen wie <code>BSW Module Behavior</code>, <code>BSW Module ...</code>, <code>Local Measurement...</code>), jeweils aggregiert mit Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Definitionsdiagramm ohne Laufzeit- oder Sequenzcharakter. Im methodischen Ablauf beschreibt es die Bereitstellung und Anreicherung von BSW-Lieferbündeln im Rahmen der Integrationsphase: Das generische Lieferbündel (<code>BSW Module Delivered Bundle</code>) wird für die konkrete ECU- und Systemintegration zum <code>BSW Module Integration Bundle</code> erweitert, indem modulspezifische Schnittstellenerweiterungen, Verhaltensmodelle und lokale Integrationsparameter gebündelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Work-Product-Struktur für AUTOSAR BSW-Lieferungen und -Integration. Entwickler und Tool-Hersteller von AUTOSAR-Authoring- und Integrationswerkzeugen müssen sicherstellen, dass Integrationsbündel alle spezialisierten Artefakte des gelieferten Bündels erben und zusätzliche integrationsspezifische Deskriptoren (0 bis n Ausprägungen pro aggregiertem Work Product) konsistent kapseln.</p>"}, {"id": "FIG-13e41b3117b6554b", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Metamodell- und Prozessdiagramm der AUTOSAR-Methodik (Work Product Definition). Das Diagramm spezifiziert die Spezialisierungshierarchie von Artefakt-Bündeln (Work Product Kinds) für die Basissoftware-Integration sowie deren Aggregation von Teil-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Paket-Artefakte (Work Product Definitions bzw. Packages) in einer Spezialisierungskette:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Bundle</code>: Basis-Artefaktpaket.\n</li><li><code>BSW Module Delivered Bundle</code>: Spezialisiert <code>BSW Module Bundle</code> über eine Generalisierungsbeziehung (<code>«extends»</code>).\n</li><li><code>BSW Module Integration Bundle</code>: Spezialisiert <code>BSW Module Delivered Bundle</code> über eine Generalisierungsbeziehung (<code>«extends»</code>).\n</li></ul>\n<p class=\"fig-p\">Vom <code>BSW Module Integration Bundle</code> gehen vier Aggregationsbeziehungen (<code>«SPEM_Aggregation»</code>) mit Kardinalität <code>0..*</code> zu einzelnen Arbeitsergebnissen/Dokumenten (Work Products) aus:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Interface Extension</code>: Zusätzliche Schnittstellendefinitionen für das BSW-Modul (Kardinalität <code>0..*</code>).\n</li><li>Drei weitere untergeordnete BSW-Artefakte am unteren Rand (BSW-Modulbeschreibungen, Verhaltensbeschreibungen und lokale Konfigurations-/Messgrößendefinitionen wie <code>BSW Module Behavior</code>, <code>BSW Module ...</code>, <code>Local Measurement...</code>), jeweils aggregiert mit Kardinalität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Definitionsdiagramm ohne Laufzeit- oder Sequenzcharakter. Im methodischen Ablauf beschreibt es die Bereitstellung und Anreicherung von BSW-Lieferbündeln im Rahmen der Integrationsphase: Das generische Lieferbündel (<code>BSW Module Delivered Bundle</code>) wird für die konkrete ECU- und Systemintegration zum <code>BSW Module Integration Bundle</code> erweitert, indem modulspezifische Schnittstellenerweiterungen, Verhaltensmodelle und lokale Integrationsparameter gebündelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Work-Product-Struktur für AUTOSAR BSW-Lieferungen und -Integration. Entwickler und Tool-Hersteller von AUTOSAR-Authoring- und Integrationswerkzeugen müssen sicherstellen, dass Integrationsbündel alle spezialisierten Artefakte des gelieferten Bündels erben und zusätzliche integrationsspezifische Deskriptoren (0 bis n Ausprägungen pro aggregiertem Work Product) konsistent kapseln.</p>"}, {"id": "FIG-b8219973e96d684e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Metamodell- und Prozessdiagramm der AUTOSAR-Methodik (Work Product Definition). Das Diagramm spezifiziert die Spezialisierungshierarchie von Artefakt-Bündeln (Work Product Kinds) für die Basissoftware-Integration sowie deren Aggregation von Teil-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Paket-Artefakte in einer Spezialisierungshierarchie:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Bundle</code>: Basis-Paket.\n</li><li><code>BSW Module Delivered Bundle</code>: Spezialisiert <code>BSW Module Bundle</code> via <code>«extends»</code>.\n</li><li><code>BSW Module Integration Bundle</code>: Spezialisiert <code>BSW Module Delivered Bundle</code> via <code>«extends»</code>.\n</li></ul>\n<p class=\"fig-p\"><code>BSW Module Integration Bundle</code> aggregiert über gerichtete Aggregationen mit dem Stereotyp <code>«aggregation»</code> und jeweiliger Kardinalität <code>0..*</code> vier untergeordnete Arbeitsergebnisse:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Interface Extension</code> (Kardinalität <code>0..*</code>)\n</li><li><code>BSW Module Behavior</code> (Kardinalität <code>0..*</code>)\n</li><li><code>BSW Module ...</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Local Measurement...</code> (Kardinalität <code>0..*</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Definitionsdiagramm ohne Laufzeit- oder Sequenzcharakter. Im methodischen Ablauf beschreibt es die Bereitstellung und Anreicherung von BSW-Lieferbündeln im Rahmen der Integrationsphase: Das generische Lieferbündel (<code>BSW Module Delivered Bundle</code>) wird für die konkrete ECU- und Systemintegration zum <code>BSW Module Integration Bundle</code> erweitert, indem modulspezifische Schnittstellenerweiterungen, Verhaltensmodelle und lokale Integrationsparameter gebündelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Work-Product-Struktur für AUTOSAR BSW-Lieferungen und -Integration. Entwickler und Tool-Hersteller von AUTOSAR-Authoring- und Integrationswerkzeugen müssen sicherstellen, dass Integrationsbündel alle spezialisierten Artefakte des gelieferten Bündels erben und zusätzliche integrationsspezifische Deskriptoren (0 bis n Ausprägungen pro aggregiertem Work Product) konsistent kapseln.</p>"}, {"id": "FIG-a7c40bf61b130e7c", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Metamodell- und Prozessdiagramm der AUTOSAR-Methodik (Work Product Definition). Das Diagramm spezifiziert die Spezialisierungshierarchie von Artefakt-Bündeln (Work Product Kinds) für die Basissoftware-Integration sowie deren Aggregation von Teil-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Paket-Artefakte in einer Spezialisierungshierarchie:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Bundle</code>: Basis-Paket.\n</li><li><code>BSW Module Delivered Bundle</code>: Spezialisiert <code>BSW Module Bundle</code> via <code>«extends»</code>.\n</li><li><code>BSW Module Integration Bundle</code>: Spezialisiert <code>BSW Module Delivered Bundle</code> via <code>«extends»</code>.\n</li></ul>\n<p class=\"fig-p\"><code>BSW Module Integration Bundle</code> aggregiert über gerichtete Aggregationen mit dem Stereotyp <code>«aggregation»</code> und jeweiliger Kardinalität <code>0..*</code> vier untergeordnete Arbeitsergebnisse:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Interface Extension</code> (Kardinalität <code>0..*</code>)\n</li><li><code>BSW Module Behavior</code> (Kardinalität <code>0..*</code>)\n</li><li><code>BSW Module ...</code> (Kardinalität <code>0..*</code>)\n</li><li><code>Local Measurement...</code> (Kardinalität <code>0..*</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Definitionsdiagramm ohne Laufzeit- oder Sequenzcharakter. Im methodischen Ablauf beschreibt es die Bereitstellung und Anreicherung von BSW-Lieferbündeln im Rahmen der Integrationsphase: Das generische Lieferbündel (<code>BSW Module Delivered Bundle</code>) wird für die konkrete ECU- und Systemintegration zum <code>BSW Module Integration Bundle</code> erweitert, indem modulspezifische Schnittstellenerweiterungen, Verhaltensmodelle und lokale Integrationsparameter gebündelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Work-Product-Struktur für AUTOSAR BSW-Lieferungen und -Integration. Entwickler und Tool-Hersteller von AUTOSAR-Authoring- und Integrationswerkzeugen müssen sicherstellen, dass Integrationsbündel alle spezialisierten Artefakte des gelieferten Bündels erben und zusätzliche integrationsspezifische Deskriptoren (0 bis n Ausprägungen pro aggregiertem Work Product) konsistent kapseln.</p>"}, {"id": "FIG-7845b3fa6cbebcf4", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Metamodell- und Prozessdiagramm der AUTOSAR-Methodik (Work Product Definition). Das Diagramm spezifiziert die Spezialisierungshierarchie von Artefakt-Bündeln (Work Product Kinds) für die Basissoftware-Integration sowie deren Aggregation von Teil-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Paket-Artefakte in einer vertikal ausgerichteten Spezialisierungshierarchie:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Bundle</code>: Oberstes Basis-Paket.\n</li><li><code>BSW Module Delivered Bundle</code>: Spezialisiert <code>BSW Module Bundle</code> via vertikaler <code>«extends»</code>-Beziehung.\n</li><li><code>BSW Module Integration Bundle</code>: Spezialisiert <code>BSW Module Delivered Bundle</code> via vertikaler <code>«extends»</code>-Beziehung.\n</li></ul>\n<p class=\"fig-p\"><code>BSW Module Integration Bundle</code> aggregiert symmetrisch aufgefächert über vier Aggregationsbeziehungen mit dem Stereotyp <code>«aggregation»</code> und jeweiliger Kardinalität <code>0..*</code> folgende untergeordnete Arbeitsergebnisse:</p>\n<ul class=\"fig-list\"><li>Erstes untergeordnetes BSW-Dokument (links, vormals Interface Extension, Kardinalität <code>0..*</code>)\n</li><li>Zweites untergeordnetes BSW-Dokument (<code>BSW Module Behavior</code>, Kardinalität <code>0..*</code>)\n</li><li>Drittes untergeordnetes BSW-Dokument (<code>BSW Module ...</code>, Kardinalität <code>0..*</code>)\n</li><li>Viertes untergeordnetes BSW-Dokument (<code>Local Measurement...</code>, Kardinalität <code>0..*</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Definitionsdiagramm ohne Laufzeit- oder Sequenzcharakter. Im methodischen Ablauf beschreibt es die Bereitstellung und Anreicherung von BSW-Lieferbündeln im Rahmen der Integrationsphase: Das generische Lieferbündel (<code>BSW Module Delivered Bundle</code>) wird für die konkrete ECU- und Systemintegration zum <code>BSW Module Integration Bundle</code> erweitert, indem modulspezifische Schnittstellenerweiterungen, Verhaltensmodelle und lokale Integrationsparameter gebündelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Work-Product-Struktur für AUTOSAR BSW-Lieferungen und -Integration. Entwickler und Tool-Hersteller von AUTOSAR-Authoring- und Integrationswerkzeugen müssen sicherstellen, dass Integrationsbündel alle spezialisierten Artefakte des gelieferten Bündels erben und zusätzliche integrationsspezifische Deskriptoren (0 bis n Ausprägungen pro aggregiertem Work Product) konsistent kapseln.</p>"}, {"id": "FIG-374d8cca717a75e8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Metamodell- und Prozessdiagramm der AUTOSAR-Methodik (Work Product Definition). Das Diagramm spezifiziert die Spezialisierungshierarchie von Artefakt-Bündeln (Work Product Kinds) für die Basissoftware-Integration sowie deren Aggregation von Teil-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Paket-Artefakte in einer vertikal ausgerichteten Spezialisierungshierarchie:</p>\n<ul class=\"fig-list\"><li><code>BSW Module Bundle</code>: Oberstes Basis-Paket.\n</li><li><code>BSW Module Delivered Bundle</code>: Spezialisiert <code>BSW Module Bundle</code> via vertikaler <code>«extends»</code>-Beziehung.\n</li><li><code>BSW Module Integration Bundle</code>: Spezialisiert <code>BSW Module Delivered Bundle</code> via vertikaler <code>«extends»</code>-Beziehung.\n</li></ul>\n<p class=\"fig-p\"><code>BSW Module Integration Bundle</code> aggregiert symmetrisch aufgefächert über vier Aggregationsbeziehungen mit dem Stereotyp <code>«aggregation»</code> und jeweiliger Kardinalität <code>0..*</code> folgende untergeordnete Arbeitsergebnisse:</p>\n<ul class=\"fig-list\"><li>Erstes untergeordnetes BSW-Dokument (links, vormals Interface Extension, Kardinalität <code>0..*</code>)\n</li><li>Zweites untergeordnetes BSW-Dokument (<code>BSW Module Behavior</code>, Kardinalität <code>0..*</code>)\n</li><li>Drittes untergeordnetes BSW-Dokument (<code>BSW Module ...</code>, Kardinalität <code>0..*</code>)\n</li><li>Viertes untergeordnetes BSW-Dokument (<code>Local Measurement...</code>, Kardinalität <code>0..*</code>)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Definitionsdiagramm ohne Laufzeit- oder Sequenzcharakter. Im methodischen Ablauf beschreibt es die Bereitstellung und Anreicherung von BSW-Lieferbündeln im Rahmen der Integrationsphase: Das generische Lieferbündel (<code>BSW Module Delivered Bundle</code>) wird für die konkrete ECU- und Systemintegration zum <code>BSW Module Integration Bundle</code> erweitert, indem modulspezifische Schnittstellenerweiterungen, Verhaltensmodelle und lokale Integrationsparameter gebündelt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Work-Product-Struktur für AUTOSAR BSW-Lieferungen und -Integration. Entwickler und Tool-Hersteller von AUTOSAR-Authoring- und Integrationswerkzeugen müssen sicherstellen, dass Integrationsbündel alle spezialisierten Artefakte des gelieferten Bündels erben und zusätzliche integrationsspezifische Deskriptoren (0 bis n Ausprägungen pro aggregiertem Work Product) konsistent kapseln.</p>"}], "trans": [{"from": "FIG-5f65348b962f04bc", "to": "FIG-50f5393d10d0966d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>BSW Module Integration Bundle</code>: Textbezeichnung des Pakets rechts neben das Paketsymbol verschoben (im vorherigen Stand überlappte der Text <code>BSW Module Integration Bundle</code> teils die Kontur bzw. war zweizeilig/abgeschnitten überlagert; <code>BSW Module Delivered Bundle</code> steht nun sauber rechts vom mittleren Paket).\n</li><li>Keine semantische Änderung an Modellelementen oder Beziehungen.\n</li></ul>"}, {"from": "FIG-50f5393d10d0966d", "to": "FIG-13e41b3117b6554b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-13e41b3117b6554b", "to": "FIG-b8219973e96d684e", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Stereotypen der Aggregationsbeziehungen: Die Bezeichner der Aggregationskanten von <code>BSW Module Integration Bundle</code> zu den untergeordneten Artefakten wurden von <code>«SPEM_Aggregation»</code> zu <code>«aggregation»</code> umbenannt.\n</li><li>Dokumentenbeschriftungen: Am unteren Bildrand sind die Dokumentenbeschriftungen der Aggregationsziele (<code>BSW Module Behavior</code>, <code>BSW Module ...</code>, <code>Local Measurement...</code>) durch geändertes Text-Clipping bzw. Rendering sichtbarer dargestellt.\n</li></ul>"}, {"from": "FIG-b8219973e96d684e", "to": "FIG-a7c40bf61b130e7c", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a7c40bf61b130e7c", "to": "FIG-7845b3fa6cbebcf4", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Layout: Die Paketvererbungskette (<code>BSW Module Bundle</code> -&gt; <code>BSW Module Delivered Bundle</code> -&gt; <code>BSW Module Integration Bundle</code>) ist nun streng vertikal zentriert angeordnet statt treppenförmig nach rechts unten versetzt.\n</li><li><code>BSW Module Interface Extension</code> bzw. linkes Aggregationsziel: Das ganz linke Dokumentensymbol ist nun symmetrisch unterhalb von <code>BSW Module Integration Bundle</code> angeordnet (mit horizontaler Kantenführung und Beschriftung <code>0..* «aggregation»</code>).\n</li><li>Kantenführung: Die Vererbungs- (<code>«extends»</code>) und Aggregationsbeziehungen (<code>«aggregation»</code>) wurden auf ein symmetrisches, vertikales Layout angepasst.\n</li></ul>"}, {"from": "FIG-7845b3fa6cbebcf4", "to": "FIG-374d8cca717a75e8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
